#!/usr/bin/env python3
"""Assemble the Round2 multiprobe STOP report. No launch or submission actions."""
from __future__ import annotations
import json
from pathlib import Path
from _r2_contracts import OUT,write_json

def read(p):return json.loads((OUT/p).read_text())
def main():
 out=OUT/'reports';out.mkdir(parents=True,exist_ok=True);inv=read('00_inventory/ASSET_INVENTORY.json');rel=read('02_reliability/DART_RELIABILITY_AUDIT.json');geo=read('04_geometry/H300/GEOMETRY_SCREEN_REPORT.json');dart=read('03_dart_eval/H300/DART_H300_REPORT.json');fda=read('06_fourier/FOURIER_FDA_REPORT.json');dp=OUT/'05_donors/BARREN_AGRI_PRELIM_AUDIT.json';don=json.loads(dp.read_text()) if dp.exists() else {'status':'INCOMPLETE'}
 b=dart['results']['BASE']['miou'];dart_rows={k:{'miou':v['miou'],'delta_pp':100*(v['miou']-b),'flip':v.get('flip_vs_theta278'),'stage_rms_delta':v['stage_rms_delta'],'head_bias_drift':v['head_bias_drift']} for k,v in dart['results'].items()}
 report={'status':'STOP','online_frozen_facts':{'theta278_oldBstar_test2_percent':70.569757,'theta261_oldBstar_test2_percent':69.639339,'matched_delta_pp':.930418,'scope':'aggregate superiority only; not per-flip truth'},'reliability':rel,'geometry':geo,'DART_H300':dart_rows,'donor':don,'fourier_FDA':fda,'decisions':{'DART_continue_4k':False,'geometry_expand_full1399':False,'FDA_train':False,'platform_slot_recommended_now':False,'platform_submission_performed':False},'test2_ground_truth_used':False,'platform_submission_performed':False}
 write_json(out/'ROUND2_MULTIPROBE_REPORT.json',report)
 lines=['# ROUND2 MULTIPROBE REPORT','', '**FINAL STATE: STOP**','', 'No platform submission, no test2 GT, no 4k continuation, no FDA training.','', '## Frozen online fact','', '- theta278 + old Bstar: **70.569757**','- theta261 + old Bstar: **69.639339**','- matched delta: **+0.930418 pp**','- This proves aggregate superiority only, not correctness of every disagreement pixel.','', '## DART reliability audit','',f"- D2 source-prior gate: **{rel['gate']['status']}**",f"- H300 selected-region source net advantage: `{rel['gate']['requirements']['H300_selected_net_advantage_point']:.4f}`; CI `{rel['gate']['requirements']['H300_selected_net_advantage_ci95']}`",f"- test2 positive-weight disagreement coverage: `{rel['gate']['requirements']['test2_positive_weight_coverage']:.4%}`",'- Prototype signal skipped: existing features are image-pooled and not pixel prototypes.','', '## DART 2k STOP gate','', '| candidate | H300 mIoU | delta vs base (pp) | flip vs base |','|---|---:|---:|---:|']
 for k,v in dart_rows.items():
  flip='' if v['flip'] is None else format(v['flip'],'.4%')
  lines.append(f"| {k} | {v['miou']:.6f} | {v['delta_pp']:+.4f} | {flip} |")
 lines += ['', '**Decision:** all D0/D1/D2 candidates degrade H300 source safety. D1@2k is least negative but still below base. D2 is worse than D1. Do not continue to 4k and do not spend a platform slot.','', '### DART hypothesis accounting','', '1. **Load-bearing assumption:** source-supported agreement/disagreement regions transfer useful teacher structure to test2.','2. **Strongest counterexample:** ordinary D0 source continuation already degrades; D2 adds further degradation.','3. **Difference from old ATDA:** weak→strong hard agreement plus source-calibrated soft disagreement, with tiny-LR head.','4. **Observation:** no candidate preserves theta278 H300 mIoU.','5. **Failure condition:** triggered.','6. **Continue 4k:** no.','7. **Future platform slot:** no.','', '## Geometry H300','', '| candidate | mIoU | delta | 95% CI | flip | strict gate |','|---|---:|---:|---:|---:|---|']
 for k,v in geo['candidates'].items():lines.append(f"| {k} | {v['miou']:.6f} | {100*v['delta_miou']:+.4f} pp | [{100*v['delta_ci95'][0]:+.4f}, {100*v['delta_ci95'][1]:+.4f}] pp | {v['mean_flip_vs_G0']:.4%} | {'PASS' if v['gate_pass'] else 'FAIL'} |")
 lines += ['', '**Decision:** total mIoU signals are positive, especially G1, but preregistered per-class safety gate fails. No full-1399 expansion and no test2 package. Retain G1 only as evidence for a future class-safe fusion design.','', '### Geometry hypothesis accounting','', '1. **Load-bearing assumption:** more local/high-resolution context repairs small structures without broad class damage.','2. **Strongest counterexample:** historical M2F multiscale was negative.','3. **Difference from old ATDA:** inference geometry only; same theta278 checkpoint.','4. **Observation:** positive aggregate H300 delta, strict class gate fails.','5. **Failure condition:** triggered.','6. **Continue full 1399 now:** no.','7. **Future platform slot:** not in current form.','', '## Heterogeneous donor','']
 if 'donor_result' in don:
  lines += [f"- Donor mIoU `{don['donor_result']['miou']:.6f}` vs theta278 `{don['theta278']['miou']:.6f}` (protocol-mismatched preliminary audit).",f"- Net repair fraction `{don['net_fraction_point']:.6f}`, CI `{don['net_fraction_ci95']}`.",f"- Retain for exact D4 cache: **{don['retain_for_exact_cache']}**.",'- Existing donor is single-view while theta278 is D4; no fusion claim is made.']
 else:lines += ['- Preliminary donor audit incomplete at report generation; no donor retained.']
 lines += ['', '## Fourier / FDA preparation','',f"- source→test1 spectral distance: `{fda['source_distance']['test1']:.6f}`",f"- source→test2 spectral distance: `{fda['source_distance']['test2']:.6f}`",f"- suggested deterministic beta: `{fda['recommended_beta']}`",f"- compliance: **{fda['compliance']}**",'- No FDA training was performed.','', '## Final decisions','', '- **DART:** stop at 2k; no 4k.','- **Geometry:** stop under strict gate; no target package.','- **Donor:** only provenance-qualified evidence; no ensemble submission.','- **FDA:** statistics/transform prep only; blocked pending rules.','- **Platform:** no submission and no package generated.','- Any next experiment requires a new explicit authorization.']
 (out/'ROUND2_MULTIPROBE_REPORT.md').write_text('\n'.join(lines)+'\n',encoding='utf-8');print('\n'.join(lines[-12:]))
if __name__=='__main__':main()
